import json, html, pathlib
R=pathlib.Path(__file__).resolve().parent.parent
rows=json.loads((R/'data/contests.json').read_text()); cats=json.loads((R/'data/categories.json').read_text())
def e(v):return html.escape(str(v),quote=True)
def link(url,text):return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(text)} ↗</a>'
def table(rs):
 s='<div class="table-wrap" tabindex="0" aria-label="Scrollable competition table"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in ['Competition / evidence','Cash prize','Deadline','Free entry','Eligibility / AI rules','Official source'])+'</tr></thead><tbody>'
 for r in rs:
  s+=f'<tr data-search="{e((r["name"]+" "+r["category"]+" "+r["notes"]).lower())}" data-status="{e(r["status"])}"><td><strong>{e(r["name"])}</strong><span class="badge {"confirmed" if r["status"].startswith("Confirmed") else ("partial" if r["checked"] else "")}">{e(r["status"])}</span><small>{e(r["notes"])}</small></td><td>{e(r["prize"])}</td><td>{e(r["deadline"])}</td><td>{e(r["free"])}</td><td>{e(r["eligibility"])}<small>{e(r["ai"])}</small></td><td>{link(r["source"],"Source" if r["checked"] else "Source · unchecked")}'+(link(r['rules'],'Official rules') if r.get('rules') else '')+f'<small>{"Checked "+r["checked"] if r["checked"] else "Not checked"}</small></td></tr>'
 return s+'</tbody></table></div><p id="empty" hidden>No matching entries. Try a different search.</p>'
summary='''<div class="callout"><strong>One confirmed free-entry cash opportunity.</strong> The ARC Prize 2026 Paper Track confirms no-purchase entry and cash awards in its official rules; participation also requires a separate ARC-AGI submission. Other leads remain unqualified until their own current rules are checked. Blank cells mean unverified—not zero, free, or unrestricted.</div><div class="insights"><article><span class="eyebrow">01 / RESEARCH PRIORITY</span><h3>Investigate GEMS first</h3><p>Official page confirms a $300,000 pool and December 3 deadline. A longer runway than ARC makes it a research candidate, not a recommendation to enter. Free entry remains unconfirmed; the official rules permit generative AI with disclosure (§3.2).</p></article><article><span class="eyebrow">02 / TIME-SENSITIVE</span><h3>ARC is almost due</h3><p>The separately verified Paper Track deadline is November 9, 23:59 UTC, with $75,000 guaranteed awards and a prerequisite prediction-track submission. Read its track-specific rules before starting.</p></article><article><span class="eyebrow">03 / PROTECT YOUR TIME</span><h3>Practice isn’t cash</h3><p>Directories, free Gems rooms and private pool tools should not be counted as confirmed free cash opportunities. No win probabilities or expected hourly returns have been invented.</p></article></div>'''
method='''<h2>Executive summary</h2><p>The supplied ledger has 206 active listings and 45 removed records. All 206 active entries are retained here, plus three specific 2026 opportunity records. Removed entries are preserved in the downloadable upstream archive, not presented as current opportunities. The original repository for this project contained only a README.</p><h3>Original-site audit</h3><ul><li>The original landing page explicitly has no search or filters; its long cards make cross-comparison difficult. This replacement uses category pages, search, evidence filters and compact tables.</li><li>The headline “189 true free paths” is an upstream claim, not re-verified evidence. It is not repeated as a verified statistic.</li><li>The page header says August 17, while its dataset says August 19, 2026. Neither proves availability on November 1.</li><li>The claim “US tax forms apply at $600+” is too broad to reuse as tax advice. No universal threshold is asserted here.</li><li>Dead external links have not been exhaustively identified. A reachable page is not proof of eligibility, payment or free entry.</li></ul><h3>Evidence standard</h3><p>Research date: November 1, 2026 (UTC). Official pages were read for Papaya FAQ, Kaggle directory, DrivenData directory, Topcoder directory, ARC 2026, GEMS overview and the linked GEMS rules PDF (sections 1.3 and A.2). Eight earlier rows have limited official evidence; the separately checked ARC Paper Track has an explicit no-purchase clause and cash awards. Personal eligibility and prerequisite challenge rules still need individual review. All other rows are imported leads with unchecked upstream-designated official destinations. Those destinations have not been independently authenticated.</p><h3>How to decide where to compete</h3><ol><li>Establish explicit free entry and a withdrawable cash award from current event rules.</li><li>Verify age, citizenship, residency, exclusions, deadlines, tax and identity requirements.</li><li>Check whether coding assistance, pretrained models, external data and APIs are permitted. Do not treat silence as permission.</li><li>Estimate your own compute cost and available time only after building a rules-compliant baseline. No evidence supports win odds or earnings rankings here.</li></ol><p>Nothing on this site enters competitions, creates accounts or submits work for you. No deposit or payment workflow is provided.</p><h3>Audit trail & downloads</h3><p><a href="data/EVIDENCE.md">Field-level evidence log</a> · <a href="data/contests.json">Normalized table data</a> · <a href="data/upstream.json">Upstream archive (unverified claims, including removed entries)</a> · <a href="https://github.com/karagemop466-tech/FreeMoneyApps/tree/466f7c1e7a14b52b4a0d36beb84a00d68fd409b7">Pinned source repository</a> · <a href="https://karagemop466-tech.github.io/FreeMoneyApps/">Original site</a></p>'''
def page(file,title,subtitle,content,active=''):
 nav='<a class="'+('active' if active=='all' else '')+'" href="index.html">▦ &nbsp; Overview</a><span class="nav-label">EXPLORE CATEGORIES</span>'+''.join(f'<a class="{"active" if active==c["id"] else ""}" href="{c["id"]}.html">{e(c["name"])} <b>{sum(r["category"]==c["id"] for r in rows)}</b></a>' for c in cats)+'<span class="nav-label">RESEARCH DESK</span><a href="review.html">⚑ &nbsp; Flagged for Review</a><a href="summary.html">Executive summary</a><a href="ledger-ebd10b79/index.html">Prize Ledger dashboard ↗</a><a href="dashboard/index.html">Verified-or-blank dashboard ↗</a><a href="audits/2026-11-01/index.html">Independent audit ↗</a>'
 (R/file).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Evidence-first research ledger of free-entry cash prize competition leads."><title>{e(title)} | PrizeDesk</title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="logo">P</span> PrizeDesk<span class="beta">RESEARCH</span></a><p class="tagline">Less searching. Better decisions.</p><nav aria-label="Main navigation">{nav}</nav><div class="aside-note"><span class="dot"></span> Evidence, not promises<br><small>Independent research · No affiliate links</small></div></aside><div class="workspace"><header><span>COMPETITION INTELLIGENCE</span><span>Updated 01 Nov 2026 <span class="dot"></span></span></header><main id="main"><p class="eyebrow">THE FREE-ENTRY CASH PRIZE LEDGER</p><h1>{e(title)}</h1><p class="subtitle">{e(subtitle)}</p>{content}</main><footer>Official rules take precedence. Blank = unverified. No earnings guarantees. <a href="summary.html">Methodology & sources</a></footer></div></body></html>''')
controls='<div class="tools"><label>Search competitions<input id="search" type="search" placeholder="Search names, categories or notes…"></label><label>Evidence<select id="evidence"><option value="">All evidence levels</option><option>Confirmed free entry + cash prize</option><option>Partial evidence</option><option>Unverified</option></select></label><span id="result-count" role="status"></span></div>'
stats='<div class="stats">'+''.join(f'<article><span>{label}</span><strong>{val}</strong><small>{note}</small></article>' for label,val,note in [('Research leads','209','206 imported + 3 event records'),('Free-entry cash path','1','Paper Track; prerequisite applies'),('Partial evidence','8','Some facts checked officially'),('Needs review','208','Unresolved fields remain')])+'</div>'
page('index.html','Find your next challenge.','Cash-prize research, without the noise. Compare the evidence before committing your time.',stats+summary+'<div class="section-heading"><h2>All competition leads</h2><a href="data/contests.json">Download data ↓</a></div><p>One Paper Track has a confirmed no-purchase cash path. All other records still need review. <a href="explore.html">View the focused shortlist →</a></p>'+controls+table(rows),'all')
for c in cats:page(c['id']+'.html',c['name'],'Browse this category. Unconfirmed terms are deliberately left blank.',controls+table([r for r in rows if r['category']==c['id']]),c['id'])
page('review.html','Flagged for Review','Published uncertainties—not hidden assumptions.',summary+'<h2>Unresolved evidence queue</h2><p>Except the ARC Paper Track, free-entry confirmation is missing. Additional blanks identify unverified prizes, dates, eligibility and AI rules. Unchecked links may be stale or incorrect; no unsupported link repair has been invented.</p>'+controls+table(rows))
page('summary.html','Executive summary','What we found, what we know, and what still needs proof.',summary+method)
page('404.html','Page not found','This research page does not exist.','<p><a href="index.html">Return to the dashboard →</a></p>')
print(f'Built 13 HTML pages; {len(rows)} records')
